entries.commands:
nmcli con show
nmcli con mod "{{con_name}}" ipv4.method manual ipv4.addresses {{ip_addr}}/{{prefix_len}}
nmcli con mod "{{con_name}}" ipv4.gateway {{gateway}}
nmcli con mod "{{con_name}}" ipv4.dns {{dns_ip}}
nmcli con up "{{con_name}}"
nmcli con show "{{con_name}}"

cp /etc/sysconfig/network-scripts/ifcfg-{{ifname}} /etc/sysconfig/network-scripts/ifcfg-{{ifname}}.bak
vi /etc/sysconfig/network-scripts/ifcfg-{{ifname}}
# DEVICE={{ifname}}
# BOOTPROTO=static
# ONBOOT=yes
# IPADDR={{ip_addr}}
# PREFIX={{prefix_len}}
# GATEWAY={{gateway}}
# DNS1={{dns_ip}}
systemctl restart NetworkManager
nmcli con show

# ---- 临时 ----
ip route add {{dest_net}}/{{prefix_len}} via {{gateway}} dev {{ifname}}
ip route show
# ---- 持久化：/etc/sysconfig/network-scripts/route-{{ifname}} ----
vi /etc/sysconfig/network-scripts/route-{{ifname}}
# {{dest_net}}/{{prefix_len}} via {{gateway}} dev {{ifname}}
systemctl restart NetworkManager
ip route show

# ---- 临时 ----
ip link add link {{ifname}} name {{ifname}}.{{vlan_id}} type vlan id {{vlan_id}}
ip addr add {{ip_addr}}/{{prefix_len}} dev {{ifname}}.{{vlan_id}}
ip link set {{ifname}}.{{vlan_id}} up
# ---- 持久化 ----
cat > /etc/sysconfig/network-scripts/ifcfg-{{ifname}}.{{vlan_id}} << 'EOF'
DEVICE={{ifname}}.{{vlan_id}}
BOOTPROTO=static
ONBOOT=yes
VLAN=yes
PHYSDEV={{ifname}}
IPADDR={{ip_addr}}
PREFIX={{prefix_len}}
EOF
systemctl restart NetworkManager
ip -d link show {{ifname}}.{{vlan_id}}

systemctl start {{service_name}}
systemctl enable --now {{service_name}}
systemctl status {{service_name}} -l --no-pager
systemctl is-enabled {{service_name}}
journalctl -u {{service_name}} -n 50 --no-pager

rpm -qpR {{pkg_name}}.rpm
rpm -Uvh ./*.rpm
rpm -q {{pkg_name}}

# 临时生效：重启后丢失（持久化见 notes 里的配套条目）
ip link set {{ifname}} up
ip addr add {{ip_addr}}/{{prefix_len}} dev {{ifname}}
ip addr show {{ifname}}
ip route get {{ip_addr}}

ethtool {{ifname}}
ethtool -S {{ifname}} | head -40
ip -s link show {{ifname}}

ping -c 4 {{target}}
traceroute -n {{target}}
dig +short {{domain}}
